INSERT INTO tcm_disease (disease_name, disease_pinyin, disease_pinyin_initial, disease_english, disease_alias, disease_category, disease_description, common_symptoms, main_features, cause_analysis, prognosis, prevention, remark, sort_order, status, created_at, updated_at) VALUES
	 ('感冒','gan mao','GM','Common Cold','伤风、风寒感冒、风热感冒','外感','感冒是感受外邪引起的一种常见外感疾病，以发热、恶寒、头痛、鼻塞、流涕、喷嚏、全身酸痛等为主要临床表现','发热，恶寒，头痛，鼻塞，流涕，喷嚏，咽喉不适','起病急，病程短，有自限性','外感六淫，风寒、风热之邪侵袭肺卫','预后良好，一般5-7天痊愈','注意保暖，避免受凉，增强体质',NULL,1,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('咳嗽','ke sou','KS','Cough','外感咳嗽、内伤咳嗽','内伤','咳嗽是指肺气上逆，发出咳声或咳出痰液的病症，有声无痰为咳，有痰无声为嗽，一般多为痰声并见','咳嗽，咳痰，胸闷，气喘','咳嗽是主要症状，可伴有其他症状','外感六淫，饮食不节，情志失调，肺肾虚弱','外感咳嗽预后良好，内伤咳嗽病程长','预防感冒，避免烟酒，调理饮食',NULL,2,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('哮喘','xiao chuan','XC','Asthma','哮证、喘证','内伤','哮喘是一种发作性的痰鸣气喘疾病，以喉中有哮鸣音，呼吸困难，甚至喘息不得平卧为主要表现','喉中哮鸣，呼吸困难，气喘，胸闷','反复发作，有季节性，夜间多发','外感六淫，饮食不当，情志失调，体虚病后','病程长，易反复发作','避免过敏原，预防感冒，增强体质',NULL,3,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('胃痛','wei tong','WT','Stomachache','胃脘痛','内伤','胃痛是指以上腹胃脘部近心窝处疼痛为主要表现的病症','胃脘部疼痛，胀满，反酸，嗳气，恶心呕吐','疼痛部位在上腹胃脘部','寒邪客胃，饮食伤胃，肝气犯胃，脾胃虚弱','预后较好，但易反复','饮食有节，忌暴饮暴食，保持心情舒畅',NULL,4,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('腹痛','fu tong','FT','Abdominal Pain','脘腹痛、少腹痛','内伤','腹痛是指胃脘以下、耻骨毛际以上部位发生疼痛为主要表现的病症','腹部疼痛，胀满，恶心呕吐，腹泻','疼痛部位在腹部','外感六淫，饮食不节，情志失调，瘀血阻滞','预后取决于病因','注意饮食卫生，避免暴饮暴食',NULL,5,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('腹泻','fu xie','FX','Diarrhea','泄泻','内伤','腹泻是指排便次数增多，粪质稀薄，或完谷不化，甚至如水样为主要表现的病症','排便次数增多，粪质稀薄，腹痛，腹胀','大便次数增多，粪质稀薄','外感六淫，饮食不节，情志失调，脾胃虚弱','急性腹泻预后良好，慢性腹泻病程长','注意饮食卫生，避免生冷油腻',NULL,6,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('便秘','bian mi','BM','Constipation','大便难','内伤','便秘是指大便秘结不通，排便时间延长，或虽有便意而排便困难为主要表现的病症','大便干结，排便困难，排便次数减少','大便干结难解','肠胃积热，气机郁滞，阴寒积滞，气血阴阳亏虚','预后一般较好','多饮水，多食蔬菜水果，养成定时排便习惯',NULL,7,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('头痛','tou tong','TT','Headache','头风','内伤','头痛是指头部某个部位或整个头部疼痛为主要表现的病症','头痛，头晕，恶心呕吐','疼痛部位在头部','外感六淫，情志失调，饮食不节，体虚劳倦','预后取决于病因','保持心情舒畅，避免过度劳累',NULL,8,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('眩晕','xuan yun','XY','Dizziness','头眩','内伤','眩晕是指头晕眼花，如坐舟车，旋转不定，不能站立，或伴有恶心呕吐、汗出等症状','头晕，目眩，恶心呕吐，站立不稳','头晕目眩，如坐舟车','肝阳上亢，气血亏虚，肾精不足，痰湿中阻','病程长，易反复','避免劳累，保持情绪稳定',NULL,9,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('中风','zhong feng','ZF','Stroke','卒中','内伤','中风是指以突然昏仆，半身不遂，口舌歪斜，语言蹇涩或不语，偏身麻木为主要表现的病症','突然昏仆，半身不遂，口舌歪斜，语言蹇涩','起病急，变化快，后遗症多','情志失调，饮食不节，劳逸失度，体虚病后','预后较差，多有后遗症','预防高血压，控制血脂，戒烟限酒',NULL,10,1,'2026-03-13 13:52:07','2026-03-13 13:52:07');
INSERT INTO tcm_disease (disease_name, disease_pinyin, disease_pinyin_initial, disease_english, disease_alias, disease_category, disease_description, common_symptoms, main_features, cause_analysis, prognosis, prevention, remark, sort_order, status, created_at, updated_at) VALUES
	 ('失眠','shi mian','SM','Insomnia','不寐','内伤','失眠是指经常不能获得正常睡眠为特征的一种病症，轻者入睡困难，或寐而不酣，时寐时醒，或醒后不能再寐，重者彻夜不眠','入睡困难，睡眠时间短，醒后疲倦','睡眠障碍为主要表现','情志失调，饮食不节，劳逸失度，心脾两虚','病程长，易反复','养成良好睡眠习惯，避免熬夜',NULL,11,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('心悸','xin ji','XJ','Palpitation','怔忡','内伤','心悸是指病人自觉心中悸动，惊惕不安，甚则不能自主的一种病症','心中悸动，惊惕不安，胸闷气短','自觉心中悸动不安','情志刺激，惊恐受吓，体虚劳倦，心血不足','预后取决于病因','保持心情舒畅，避免过度劳累',NULL,12,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('胸痹','xiong bi','XB','Chest Pain','心痛','内伤','胸痹是指胸部闷痛，甚则胸痛彻背，气短喘息不得卧为主要表现的病症','胸部闷痛，胸痛彻背，气短喘息','疼痛部位在胸部','寒邪内侵，情志失调，饮食不当，年老体虚','预后较差，易复发','低盐低脂饮食，避免情绪激动',NULL,13,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('黄疸','huang dan','HD','Jaundice','黄病','内伤','黄疸是以目黄、身黄、小便黄为主要特征的病症，其中目睛黄染为主要诊断依据','目黄，身黄，小便黄，发热，乏力','目睛黄染为主要诊断依据','外感湿热疫毒，饮食不节，酒食过度，积聚转化','预后取决于病因','注意饮食卫生，避免过量饮酒',NULL,14,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('水肿','shui zhong','SZ','Edema','浮肿','内伤','水肿是指体内水液潴留，泛滥肌肤，引起头面、眼睑、四肢、腹背甚至全身浮肿为主要表现的病症','身体浮肿，小便短少，体重增加','身体浮肿，小便短少','外感六淫，饮食不节，劳倦过度，体虚病后','预后取决于病因','低盐饮食，避免劳累',NULL,15,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('消渴','xiao ke','XK','Diabetes','消瘅','内伤','消渴是以多饮、多食、多尿、乏力、消瘦，或尿有甜味为主要特征的一种病症','多饮，多食，多尿，消瘦，乏力','三多一少为主要特征','饮食不节，情志失调，劳欲过度','病程长，易合并并发症','合理饮食，控制体重，适当运动',NULL,16,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('腰痛','yao tong','YT','Low Back Pain','肾虚腰痛','内伤','腰痛是指腰部一侧或两侧或正中发生疼痛为主要表现的病症','腰部疼痛，活动受限，晨起僵硬','疼痛部位在腰部','外感六淫，跌仆闪挫，体虚劳倦','病程长，易反复','避免久坐，适当运动，注意保暖',NULL,17,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('痹证','bi zheng','BZ','Arthralgia','风湿','内伤','痹证是指由于风、寒、湿、热等外邪侵袭人体，闭阻经络，气血运行不畅，导致肌肉、筋骨、关节发生酸痛、麻木、重着、屈伸不利，甚或关节肿大灼热为主要表现的病症','关节疼痛，麻木，重着，肿胀，活动受限','关节疼痛，屈伸不利','外感风寒湿热之邪，正气不足，卫外不固','病程长，易反复','注意保暖，避免受凉，增强体质',NULL,18,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('痫证','dian xian','DX','Epilepsy','羊癫疯','内伤','痫证是一种发作性神志异常疾病，以突然意识丧失，发作前常有眩晕、胸闷、等先兆，随即突然昏倒，不省人事，两目上视，口吐涎沫，四肢抽搐为主要表现','突然意识丧失，四肢抽搐，口吐涎沫','突然发作，抽搐神昏','先天因素，七情失调，脑部外伤，饮食不节','病程长，难治愈','避免情绪刺激，保证充足睡眠',NULL,19,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('血证','xue zheng','XZ','Bleeding Syndrome','出血','内伤','血证是指血液不循经脉运行，溢出脉外，或渗于肌肤之间，或积于体内，或随呕吐、咳嗽、便尿而出，表现为出血症状的病症','咯血，呕血，便血，尿血，皮肤紫斑','出血为主要表现','外感六淫，情志失调，饮食不节，劳倦过度','预后取决于病因','避免外伤，预防感染',NULL,20,1,'2026-03-13 13:52:07','2026-03-13 13:52:07');
INSERT INTO tcm_disease (disease_name, disease_pinyin, disease_pinyin_initial, disease_english, disease_alias, disease_category, disease_description, common_symptoms, main_features, cause_analysis, prognosis, prevention, remark, sort_order, status, created_at, updated_at) VALUES
	 ('汗证','han zheng','HZ','Hyperhidrosis','自汗盗汗','内伤','汗证是指由于阴阳失调，营卫不和，腠理开阖不利，而引起汗液外泄失常的一类病证，以全身或局部非正常出汗为主要表现','自汗，盗汗，大汗淋漓','汗出异常，不分时间','外感六淫，饮食不节，劳倦过度，体虚病后','预后一般较好','注意保暖，避免过度劳累',NULL,21,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('郁证','yu zheng','YZ','Depression','肝郁','内伤','郁证是由于情志不舒，气机郁滞所引起的病证，以心情抑郁，情绪不宁，胸胁胀满，易怒易哭为主要表现','心情抑郁，情绪不宁，胸胁胀满','情志失调为主要表现','情志内伤，体质虚弱','病程长，易反复','保持心情舒畅，避免情志刺激',NULL,22,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('淋证','lin zheng','LZ','Strangury','热淋','内伤','淋证是指以小便频数短涩，淋沥刺痛，小腹拘急引痛为主要表现的病症','尿频，尿急，尿痛，小便淋沥','小便频数短涩，淋沥刺痛','外感湿热，饮食不节，情志失调，体虚劳倦','预后一般较好','多饮水，注意个人卫生',NULL,23,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('遗精','yi jing','YJ','Spermatorrhea','滑精','内伤','遗精是指不因性生活而精液遗泄的病症，有梦而遗精者为梦遗，无梦而遗精，甚至清醒时精液流出者为滑精','梦遗，滑精，头晕乏力','不因性生活而遗泄精液','情志失调，饮食不节，劳欲过度，体虚病后','病程长，易反复','避免过度劳累，节制房事',NULL,24,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('阳痿','yang wei','YW','Impotence','阴痿','内伤','阳痿是指成年男子性交时，由于阴茎痿软不举，或举而不坚，或坚而不久，无法进行正常性生活为主要表现的病症','阴茎痿软不举，举而不坚','性交时阴茎不能勃起','情志失调，惊恐伤肾，饮食不节，劳欲过度','病程长，易反复','保持心情舒畅，避免过度劳累',NULL,25,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('不孕','bu yun','BY','Infertility','女子不孕','妇科','不孕是指女子婚后夫妇同居两年以上，配偶生殖功能正常，未避孕而未受孕为主要表现的病症','婚后未避孕而未受孕','同居两年以上未避孕而未受孕','肾虚，血瘀，痰湿，肝郁','预后取决于病因','保持心情舒畅，注意经期卫生',NULL,26,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('痛经','tong jing','TJ','Dysmenorrhea','经期腹痛','妇科','痛经是指妇女正值经期或行经前后，出现周期性小腹疼痛，或痛引腰骶，甚至剧痛昏厥为主要表现的病症','经期小腹疼痛，或痛引腰骶','周期性小腹疼痛','情志失调，感受寒湿，饮食不节，体虚劳倦','病程长，易反复','注意经期保暖，保持心情舒畅',NULL,27,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('带下病','dai xia bing','DXB','Leukorrhea','白带异常','妇科','带下病是指带下量明显增多或减少，色、质、气味异常，或伴有全身或局部症状为主要表现的病症','带下量增多或减少，色质气味异常','带下色质气味异常','脾虚，肾虚，湿热，湿毒','预后一般较好','注意个人卫生，避免过度劳累',NULL,28,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('乳癖','ru pi','RP','Hyperplasia of Mammary Glands','乳腺增生','外科','乳癖是指乳中生核，形如鸡卵，表面光滑，推之可移，不痛或微痛，或伴有乳房胀痛的病症','乳房肿块，乳房胀痛','乳中生核，推之可移','肝郁气滞，痰瘀互结，冲任失调','病程长，易反复','保持心情舒畅，定期检查',NULL,29,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('瘰疬','luo li','LL','Scrofula','淋巴结核','外科','瘰疬是指多发于颈项部，结块累累如珠，推之可移，溃后脓水清稀，久不收口为主要表现的病症','颈项部结块累累如珠，溃后久不收口','颈项部结块累累如珠','情志失调，饮食不节，感受外邪，体虚劳倦','病程长，易反复','保持心情舒畅，增强体质',NULL,30,1,'2026-03-13 13:52:07','2026-03-13 13:52:07');
INSERT INTO tcm_disease (disease_name, disease_pinyin, disease_pinyin_initial, disease_english, disease_alias, disease_category, disease_description, common_symptoms, main_features, cause_analysis, prognosis, prevention, remark, sort_order, status, created_at, updated_at) VALUES
	 ('虚劳','xu lao','XL','Consumptive Disease','劳损、虚损','内伤','虚劳是由于禀赋薄弱、后天失调、外感内伤等多种原因引起的，以脏腑亏损、气血阴阳虚衰为主要表现的慢性衰弱性病症','神疲乏力，气短懒言，自汗盗汗，消瘦','脏腑亏损，气血阴阳虚衰','先天不足，后天失调，饮食不节，情志失调，劳逸失度','病程长，恢复慢','调理饮食，劳逸结合，增强体质',NULL,31,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('肝病','gan bing','GB','Liver Disease','肝气郁结、肝火上炎','内伤','肝病是指肝脏功能失调或肝脏实质病变引起的疾病，以情志失调、胁肋疼痛、黄疸、腹胀等为主要表现','胸胁胀满，情志抑郁，头晕目眩','肝脏功能失调为主要表现','情志失调，饮食不节，劳倦过度','病程长，易反复','保持心情舒畅，避免熬夜',NULL,32,1,'2026-03-13 13:52:07','2026-03-13 13:52:07'),
	 ('肾病','shen bing','SB','Kidney Disease','肾虚、肾炎','内伤','肾病是指肾脏功能失调或肾脏实质病变引起的疾病，以腰膝酸软、水肿、小便异常等为主要表现','腰膝酸软，水肿，小便异常','肾脏功能失调为主要表现','先天不足，房劳过度，饮食不节','病程长，恢复慢','节制房事，避免劳累',NULL,33,1,'2026-03-13 13:52:07','2026-03-13 13:52:07');
